const med=xs=>{const a=[...xs].sort((a,b)=>a-b);return(a[Math.floor((a.length-1)/2)]+a[Math.ceil((a.length-1)/2)])/2;};
const MiB=1048576;
const runs=manifest.jobs.map(job=>({job,result:load(job.name+'.json')}));
for(const {job,result}of runs){assert(result.completed);assert.equal(result.iterations.length,job.iterations);for(const i of result.iterations)assert.equal(i.verifiedNodes,job.count);}
const scale=[16384,65536,131072,262144,524288,1048576].map(count=>{
 const found=runs.filter(x=>x.job.name.startsWith('scale-')&&x.job.count===count).map(x=>x.result);assert.equal(found.length,3);
 const rss=found.map(x=>x.peakRssBytes/MiB);
 return{count,identityBytes:found[0].identityBytes,peakRssMiB:med(rss),minRssMiB:Math.min(...rss),maxRssMiB:Math.max(...rss),retainedHeapMiB:med(found.map(x=>x.finalAfterGc.heapUsed/MiB)),medianReadMs:med(found.map(x=>med(x.iterations.map(i=>i.ms))))};
});
function fit(points,key){const mx=points.reduce((s,p)=>s+p.count,0)/points.length,my=points.reduce((s,p)=>s+p[key],0)/points.length;const slope=points.reduce((s,p)=>s+(p.count-mx)*(p[key]-my),0)/points.reduce((s,p)=>s+(p.count-mx)**2,0);const intercept=my-slope*mx;const residual=points.reduce((s,p)=>s+(p[key]-intercept-slope*p.count)**2,0);const total=points.reduce((s,p)=>s+(p[key]-my)**2,0);return{interceptMiB:intercept,bytesPerNode:slope*MiB,rSquared:1-residual/total};}
const peakFit=fit(scale.slice(0,-1),'peakRssMiB');
const held=scale.at(-1);const predicted=peakFit.interceptMiB+peakFit.bytesPerNode*held.count/MiB;
const soak=load('soak-stream-1m-40.json'),baseline=load('baseline-1m-12.json');
const previous=JSON.parse(fs.readFileSync(path.join(state,'../pipeline-3805/memory-scaling-20261103/v2/cooperative-direct-1m-natural-40.json')));
const stream12=Math.max(...soak.iterations.slice(0,12).map(i=>i.maxRssKiB))*1024;
const base12=Math.max(...baseline.iterations.slice(0,12).map(i=>i.maxRssKiB))*1024;
const widths=[128,512].map(width=>{const f=runs.filter(x=>x.job.name.startsWith('width-')&&x.job.width===width).map(x=>x.result);assert.equal(f.length,3);return{width,count:65536,identityBytes:f[0].identityBytes,peakRssMiB:med(f.map(x=>x.peakRssBytes/MiB)),minRssMiB:Math.min(...f.map(x=>x.peakRssBytes/MiB)),maxRssMiB:Math.max(...f.map(x=>x.peakRssBytes/MiB))};});
const summary={protocol:load('memory-protocol.json'),processes:runs.length,completeVerifications:runs.reduce((n,x)=>n+x.result.iterations.length,0),scale,widths,peakFit,heldOut:{count:held.count,predictedMiB:predicted,observedMiB:held.peakRssMiB,errorPct:(held.peakRssMiB/predicted-1)*100},retainedHeapFit:fit(scale,'retainedHeapMiB'),soak:{nodes:1048576,reads:40,peakRssMiB:soak.peakRssBytes/MiB,previousProbePeakRssMiB:previous.peakRssBytes/MiB,changeVsPreviousProbePct:(soak.peakRssBytes/previous.peakRssBytes-1)*100,initialHeapMiB:soak.initial.heapUsed/MiB,finalHeapMiB:soak.finalAfterGc.heapUsed/MiB,medianReadMs:med(soak.iterations.map(i=>i.ms))},matched12:{baselinePeakRssMiB:base12/MiB,streamPeakRssMiB:stream12/MiB,changePct:(stream12/base12-1)*100,baselineMedianMs:med(baseline.iterations.map(i=>i.ms)),streamMedianMs:med(soak.iterations.slice(0,12).map(i=>i.ms))},raw:runs};
